<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetAttributes;
use Civi\Lughauth\Features\Document\Snippet\Domain\Snippet;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetFilter;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetCursor;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetReadGateway;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetSlide;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetReadGateway $readGateway,
        private readonly SnippetWriteGateway $writeGateway,
        private readonly TenantVisibilityService $tenantVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(Snippet $content): SnippetAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(Snippet $content): SnippetAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(SnippetAttributes $attributes, ?Snippet $original = null): SnippetAttributes
    {
        $this->logDebug("Copy with fixed for Snippet");
        $span = $this->startSpan("Copy with fixed for  Snippet");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new SnippetPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(SnippetAttributes $attributes, ?Snippet $original = null): SnippetAttributes
    {
        $this->logDebug("Copy with hidden for Snippet");
        $span = $this->startSpan("Copy with hidden for  Snippet");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|SnippetRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Snippet");
        $span = $this->startSpan("Check visibility of an iterator for  Snippet");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new SnippetRef($value));
            } elseif ($value instanceof SnippetRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new SnippetFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(SnippetFilter $filter, ?SnippetCursor $cursor = null): SnippetSlide
    {
        $this->logDebug("List visibles for Snippet");
        $span = $this->startSpan("List visibles for  Snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (Snippet $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(SnippetFilter $filter): int
    {
        $this->logDebug("Count visibles for Snippet");
        $span = $this->startSpan("Count visibles for  Snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(SnippetFilter $filter, ?SnippetCursor $cursor = null): SnippetSlide
    {
        $this->logDebug("List visibles for update for Snippet");
        $span = $this->startSpan("List visibles for update for  Snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (Snippet $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(SnippetFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Snippet");
        $span = $this->startSpan("Count visibles for update for  Snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(SnippetRef $ref): ?Snippet
    {
        $this->logDebug("Retrieve visible for Snippet");
        $span = $this->startSpan("Retrieve visible for  Snippet");
        try {
            $filter = new SnippetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(SnippetRef $ref): ?Snippet
    {
        $this->logDebug("Retrieve visible for update for Snippet");
        $span = $this->startSpan("Retrieve visible for update for  Snippet");
        try {
            $filter = new SnippetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?SnippetRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Snippet");
        $span = $this->startSpan("Check fields for fix for Snippet");
        try {
            $result = $this->dispatcher->dispatch(new SnippetCollectNonEditableFields(Snippet::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?SnippetRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Snippet");
        $span = $this->startSpan("Check fields to hide for  Snippet");
        try {
            $result = $this->dispatcher->dispatch(new SnippetCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(SnippetAttributes $attributes): SnippetAttributes
    {
        $this->logDebug("Check visibility of parent references for Snippet");
        $span = $this->startSpan("Check visibility of parent references for  Snippet");
        try {
            $tenant = $attributes->getTenant();
            if (null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant)) {
                throw new NotFoundException("Unknown Tenant " . ($tenant->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(SnippetFilter $filter): SnippetFilter
    {
        $this->logDebug("Compose visibility filter for Snippet");
        $span = $this->startSpan("Compose visibility filter for  Snippet");
        try {
            $result = $this->dispatcher->dispatch(new SnippetRestrictFilterToVisibility($filter));
            return $result->snippetFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(Snippet $value): bool
    {
        $this->logDebug("Check if item is visible for Snippet");
        $span = $this->startSpan("Check if item is visible for  Snippet");
        try {
            $result = $this->dispatcher->dispatch(new SnippetVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(Snippet $content, bool $inlist): SnippetAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Snippet");
        $span = $this->startSpan("Prepare hydration to visible data for Snippet");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new SnippetEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
